104	/* 根据扩展名判断文件类型 */
105	static int file_type_from_name(const char *name)
106	{
107	    const char *dot = strrchr(name, '.');
108	    if (!dot) return FILE_TYPE_OTHER;
109	    if (strcasecmp(dot, ".txt") == 0) return FILE_TYPE_TXT;
110	    if (strcasecmp(dot, ".mp3") == 0 || strcasecmp(dot, ".wav") == 0) return FILE_TYPE_MP3;
111	    if (strcasecmp(dot, ".jpg") == 0 || strcasecmp(dot, ".png") == 0) return FILE_TYPE_IMG;
112	    return FILE_TYPE_OTHER;
113	}
