115	/* 扫描目录 */
116	static void files_scan_dir(const char *path)
117	{
118	    DIR *dir = opendir(path);
119	    if (!dir) { files_count = 0; return; }
120	
121	    files_count = 0;
122	    struct dirent *ent;
123	    while ((ent = readdir(dir)) != NULL && files_count < FILES_MAX_ENTRIES) {
124	        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;
125	
126	        char full[256];
127	        snprintf(full, sizeof(full), "%s/%s", path, ent->d_name);
128	
129	        struct stat st;
130	        if (stat(full, &st) != 0) continue;
131	
132	        int type = S_ISDIR(st.st_mode) ? FILE_TYPE_DIR : file_type_from_name(ent->d_name);
133	
134	        strncpy(files_paths[files_count], full, sizeof(files_paths[0]) - 1);
135	        strncpy(files_names[files_count], ent->d_name, sizeof(files_names[0]) - 1);
136	        files_types[files_count] = type;
137	        files_sizes[files_count] = S_ISDIR(st.st_mode) ? 0 : (long)st.st_size;
138	        files_selected[files_count] = 0;
139	        files_count++;
140	    }
141	    closedir(dir);
142	
143	    /* 排序：目录在前、按名称升序（安卓文件管理器默认行为） */
144	    for (uint32_t i = 1; i < files_count; i++) {
145	        uint32_t j = i;
146	        while (j > 0) {
147	            int a_dir = (files_types[j - 1] == FILE_TYPE_DIR);
148	            int b_dir = (files_types[j] == FILE_TYPE_DIR);
149	            int swap = 0;
150	            if (a_dir != b_dir)            swap = b_dir;          /* 目录优先 */
151	            else if (strcmp(files_names[j - 1], files_names[j]) > 0) swap = 1; /* 名称升序 */
152	            if (!swap) break;
153	
154	            char tmp_p[256], tmp_n[64];
155	            int  tmp_t; long tmp_s;
156	            strcpy(tmp_p, files_paths[j - 1]);   strcpy(files_paths[j - 1], files_paths[j]);   strcpy(files_paths[j], tmp_p);
157	            strcpy(tmp_n, files_names[j - 1]);   strcpy(files_names[j - 1], files_names[j]);   strcpy(files_names[j], tmp_n);
158	            tmp_t = files_types[j - 1];          files_types[j - 1] = files_types[j];          files_types[j] = tmp_t;
159	            tmp_s = files_sizes[j - 1];          files_sizes[j - 1] = files_sizes[j];          files_sizes[j] = tmp_s;
160	            j--;
161	        }
162	    }
163	}
