64	lv_result_t lv_event_send(lv_event_list_t * list, lv_event_t * e, bool preprocess)
65	{
66	    lv_result_t res = LV_RESULT_OK;
67	    if(list == NULL) return res;
68	
69	    uint32_t i = 0;
70	    /*In the callback , the 'lv_event_send' function is triggered again.*/
71	    bool is_traversing = lv_event_has_flag(list, LV_EVENT_FLAG_TRAVERSING);
72	    lv_event_add_flag(list, LV_EVENT_FLAG_TRAVERSING);
73	    uint32_t size = lv_array_size(&list->array);
74	    for(i = 0; i < size; i++) {
75	        lv_event_dsc_t ** element = lv_array_at(&list->array, i);
76	        if(element == NULL || *element == NULL || (*element)->cb == NULL) continue;
77	        lv_event_dsc_t * dsc = *element;
78	        bool is_preprocessed = (dsc->filter & LV_EVENT_PREPROCESS) != 0;
79	        if(is_preprocessed != preprocess) continue;
80	        lv_event_code_t filter = dsc->filter & ~LV_EVENT_PREPROCESS;
81	        if(filter == LV_EVENT_ALL || filter == e->code) {
82	            e->user_data = dsc->user_data;
83	            dsc->cb(e);
84	            if(e->stop_processing) break;
85	            /*Stop if the object is deleted*/
86	            if(e->deleted) return LV_RESULT_INVALID;
87	        }
88	    }
89	    if(!is_traversing) {
90	        lv_event_remove_flag(list, LV_EVENT_FLAG_TRAVERSING);
91	    }
92	    if(!is_traversing && lv_event_has_flag(list, LV_EVENT_FLAG_REMOVED)) {
93	        LV_TRACE_EVENT("Delay delete begin,event list : %" PRIu32, size);
94	        lv_event_dsc_t ** dsc_null = NULL;
95	
96	        for(i = 0; i < lv_array_size(&list->array);) {
97	            dsc_null = lv_array_at(&list->array, i);
98	            if(*dsc_null == NULL) {
99	                lv_array_remove(&list->array, i);
100	                LV_TRACE_EVENT("Event list is compacted. index: %" PRIu32, i);
101	                continue;
102	            }
103	            ++i;
104	        }
105	        LV_TRACE_EVENT("Delay delate end,event list : %" PRIu32, i);
106	        lv_event_remove_flag(list, LV_EVENT_FLAG_REMOVED);
107	        if(i != size) {
108	            lv_array_resize(&list->array, i);
109	        }
110	    }
111	    return res;
112	}
