74	    for (int d = 0; d < 3; d++) {
75	        dir = opendir(dirs[d]);
76	        if (dir == NULL)
77	            continue;
78	
79	        while ((ent = readdir(dir)) != NULL && count < DM_MAX_BOOKS) {
80	            const char *dot = strrchr(ent->d_name, '.');
81	            if (dot == NULL || dot == ent->d_name)
82	                continue;
