84	                continue;
85	
86	            /* 去重：同名文件只保留第一个（优先顺序见上） */
87	            int dup = 0;
88	            for (int i = 0; i < count; i++) {
89	                if (strcmp(seen[i], ent->d_name) == 0) {
90	                    dup = 1;
91	                    break;
92	                }
93	            }
94	            if (dup)
95	                continue;
96	
97	            strcpy(seen[count], ent->d_name);
98	            snprintf(dm_book_paths[count], sizeof(dm_book_paths[count]),
99	                     "%s/%s", dirs[d], ent->d_name);
100	            snprintf(dm_book_titles[count], sizeof(dm_book_titles[count]),
101	                     "%.*s", (int)(dot - ent->d_name), ent->d_name);
102	            count++;
103	        }
104	        closedir(dir);
105	    }
106	
107	    dm_book_count = count;
108	    return count;
109	}
