525	/* UTF-8 边界安全截断 */
526	static int book_utf8_trim(char *buf, int len)
527	{
528	    if (len <= 0) return 0;
529	    int n = len;
530	    while (n > 0) {
531	        unsigned char c = (unsigned char)buf[n - 1];
532	        if ((c & 0x80) == 0) break;
533	        if ((c & 0xC0) == 0xC0) break;
534	        n--;
535	    }
536	    buf[n] = '\0';
537	    return n;
538	}
