```c
/* P0-1：取书名首字符（完整 UTF-8，最多 3 字节），中文不乱码 */
static void book_first_char(const char *s, char out[8])
{
    if (!s || !*s) { strcpy(out, "?"); return; }
    unsigned char c = (unsigned char)s[0];
    int n = 1;
    if ((c & 0xE0) == 0xC0) n = 2;        /* 2 字节 */
    else if ((c & 0xF0) == 0xE0) n = 3;   /* 3 字节（中文） */
    else if ((c & 0xF8) == 0xF0) n = 4;   /* 4 字节 */
    if (n > 4) n = 1;
    memcpy(out, s, n);
    out[n] = '\0';
}
```

注意边界：s 是 dm_book_titles 元素（64 字节数组，null 结尾）。如果 n=3 但 s[0] 后不足（异常），memcpy 可能越界读？s 是 null 结尾的，memcpy(out, s, n) 读 n 字节，若 s 只有 1 字节 + null，读 3 字节会越界。更安全的方式：逐字节复制并检查：

```c
static void book_first_char(const char *s, char out[8])
{
    if (!s || !*s) { strcpy(out, "?"); return; }
    unsigned char c = (unsigned char)s[0];
    int n = 1;
    if ((c & 0xE0) == 0xC0 && s[1]) n = 2;
    else if ((c & 0xF0) == 0xE0 && s[1] && s[2]) n = 3;
    else if ((c & 0xF8) == 0xF0 && s[1] && s[2] && s[3]) n = 4;
    for (int i = 0; i < n; i++) out[i] = s[i];
    out[n] = '\0';
}
```

这样安全。

