static void book_apply_eye_style(void)
{
    uint32_t bg, tx, bar_bg, btn_bg, sec_tx;
    switch (g_eye_care_mode) {
    case 1:  bg = BOOK_BG_EYE;  tx = BOOK_TX_EYE;  bar_bg = 0xF3EFE6; btn_bg = 0xFFFFFF; sec_tx = 0x8A7E70; break;
    case 2:  bg = BOOK_BG_DARK; tx = BOOK_TX_DARK; bar_bg = 0x2C2C2E; btn_bg = 0x2C2C2E; sec_tx = 0x9A9A9E; break;
    default: bg = BOOK_BG_NORMAL; tx = BOOK_TX_NORMAL; bar_bg = 0xFFFFFF; btn_bg = COL_BG; sec_tx = COL_SEC; break;
    }
    if (book_reader_overlay) lv_obj_set_style_bg_color(book_reader_overlay, lv_color_hex(bg), 0);
    if (book_reader_text) lv_obj_set_style_text_color(book_reader_text, lv_color_hex(tx), 0);
    if (book_reader_title_lbl) lv_obj_set_style_text_color(book_reader_title_lbl, lv_color_hex(tx), 0);
    if (book_reader_page_lbl) lv_obj_set_style_text_color(book_reader_page_lbl, lv_color_hex(tx), 0);
    if (book_reader_prog) lv_obj_set_style_text_color(book_reader_prog, lv_color_hex(sec_tx), 0);
    /* 底部控件条 + 顶部按钮随档位（P0-2：黑档全黑，不再白条） */
    if (book_reader_bar) lv_obj_set_style_bg_color(book_reader_bar, lv_color_hex(bar_bg), 0);
