static void create_games_subpage(lv_obj_t *parent)
{
    static const struct {
        const char *name;
        const char *desc;
        const char *symbol;
        uint32_t    color;
    } games[] = {
        { "Tetris",  "Classic block puzzle",  LV_SYMBOL_PLAY,     COL_RED    },
        { "Snake",   "Retro arcade",          LV_SYMBOL_SHUFFLE,  COL_GREEN  },
        { "2048",    "Number puzzle",          LV_SYMBOL_LIST,     COL_BLUE   },
        { "Puzzle",  "Brain training",         LV_SYMBOL_EYE_OPEN,COL_PURPLE  },
    };

    /* Column, top-aligned — iOS-style large title above the game grid
     * 2026-08-09 修复：pad_row 4→DM(6)，与 Files/Books 层间距统一 */
    lv_obj_set_flex_flow(parent, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(parent, DM(6), 0);

    subpage_big_title(parent, "Games");

    /* Flex wrap grid — 2026-08-09 修复：2×2 大卡（840×360）→ 4 列紧凑卡
     * （396×216），对齐 Books 书架 6 列紧凑风格，消空白显精炼 */
    lv_obj_t *grid = make_clean_cont(parent);
    lv_obj_set_width(grid, lv_pct(100));
    lv_obj_set_height(grid, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(grid, LV_FLEX_FLOW_ROW_WRAP);
    lv_obj_set_style_pad_column(grid, CARD_GAP, 0);
    lv_obj_set_style_pad_row(grid, CARD_GAP, 0);
    lv_obj_set_flex_align(grid, LV_FLEX_ALIGN_START,
                          LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START);

    lv_coord_t sw = lv_disp_get_hor_res(lv_disp_get_default());
    lv_coord_t card_w = (sw - 2 * EDGE_PAD - 3 * CARD_GAP) / 4;
    lv_coord_t card_h = DM(90);

    for (int i = 0; i < 4; i++) {
        /* Liquid Glass 白玻璃卡：白底 + 白边 + 柔和阴影（对齐 Files/Books） */
        lv_obj_t *card = lv_obj_create(grid);
        lv_obj_set_size(card, card_w, card_h);
        lv_obj_add_style(card, &style_card, 0);
        lv_obj_set_style_pad_all(card, DM(4), 0);
        lv_obj_set_style_pad_column(card, DM(6), 0);
        lv_obj_set_style_border_width(card, 1, 0);
        lv_obj_set_style_border_color(card, lv_color_hex(0xFFFFFF), 0);
        lv_obj_set_style_border_opa(card, LV_OPA_50, 0);
        lv_obj_set_scrollbar_mode(card, LV_SCROLLBAR_MODE_OFF);
        lv_obj_clear_flag(card, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_add_flag(card, LV_OBJ_FLAG_CLICKABLE);
        /* 按压反馈：轻微放大 + 阴影加深（对齐书架卡） */
        lv_obj_set_style_transform_width(card, 3, LV_STATE_PRESSED);
        lv_obj_set_style_transform_height(card, 3, LV_STATE_PRESSED);
        lv_obj_set_style_shadow_width(card, 20, LV_STATE_PRESSED);
        lv_obj_set_style_shadow_opa(card, LV_OPA_30, LV_STATE_PRESSED);

        /* Flex row: icon badge left, name + desc right（对齐 Files 行卡） */
        lv_obj_set_flex_flow(card, LV_FLEX_FLOW_ROW);
        lv_obj_set_flex_align(card, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_CENTER,
                              LV_FLEX_ALIGN_CENTER);
        lv_obj_set_style_pad_row(card, 0, 0);

        /* Colored icon badge */
        lv_obj_t *badge = lv_obj_create(card);
        lv_obj_set_size(badge, DM(44), DM(44));
        lv_obj_set_style_radius(badge, RAD_CARD, 0);
        lv_obj_set_style_bg_color(badge, lv_color_hex(games[i].color), 0);
        lv_obj_set_style_bg_opa(badge, LV_OPA_COVER, 0);
        lv_obj_set_style_shadow_width(badge, 8, 0);
        lv_obj_set_style_shadow_color(badge, lv_color_hex(games[i].color), 0);
        lv_obj_set_style_shadow_opa(badge, LV_OPA_30, 0);
        lv_obj_set_style_border_width(badge, 0, 0);
        lv_obj_set_style_pad_all(badge, 0, 0);
        lv_obj_set_scrollbar_mode(badge, LV_SCROLLBAR_MODE_OFF);
        lv_obj_clear_flag(badge, LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_clear_flag(badge, LV_OBJ_FLAG_CLICKABLE);

        lv_obj_t *icon = lv_label_create(badge);
        lv_label_set_text(icon, games[i].symbol);
        lv_obj_set_style_text_font(icon, FONT_ICON, 0);
        lv_obj_set_style_text_color(icon, lv_color_hex(0xFFFFFF), 0);
        lv_obj_center(icon);

        /* 文字列：名称 FONT_BODY + 描述 FONT_CAPTION（主次分明） */
        lv_obj_t *tcol = make_clean_cont(card);
        lv_obj_set_height(tcol, LV_SIZE_CONTENT);
        lv_obj_set_flex_grow(tcol, 1);
        lv_obj_set_flex_flow(tcol, LV_FLEX_FLOW_COLUMN);
        lv_obj_set_style_pad_row(tcol, DM(2), 0);

        lv_obj_t *name = lv_label_create(tcol);
        lv_label_set_text(name, games[i].name);
        lv_obj_set_style_text_font(name, FONT_BODY, 0);
        lv_obj_set_style_text_color(name, lv_color_hex(COL_TEXT), 0);

        lv_obj_t *desc = lv_label_create(tcol);
        lv_label_set_text(desc, games[i].desc);
        lv_obj_set_style_text_font(desc, FONT_CAPTION, 0);
        lv_obj_set_style_text_color(desc, lv_color_hex(COL_SEC), 0);
    }
}

